// Program.cs
builder.Services.AddTransient<IEmailService, EmailService>();
// New instance every time

builder.Services.AddScoped<IShoppingCart, ShoppingCart>();
// One instance per HTTP request

builder.Services.AddSingleton<ILogger, Logger>();
// One instance for app lifetime

// Transient: lightweight, stateless services
// Scoped: per-request state (DB context, cart)
// Singleton: shared state, thread-safe only

// BAD: injecting scoped service into singleton
public class BadCacheService(IShoppingCart cart) // cart is scoped
{
    // This captures the first request's cart forever!
}

// GOOD: inject IServiceProvider and create scope
public class BackgroundJobService(IServiceProvider provider)
{
    public async Task DoWorkAsync()
    {
        using var scope = provider.CreateScope();
        var cart = scope.ServiceProvider.GetRequiredService<IShoppingCart>();
        // Use cart within this scope
    }
}

// Also use IOptions pattern for singleton config
builder.Services.AddSingleton<IConfigService>(sp =>
{
    var config = sp.GetRequiredService<IConfiguration>();
    return new ConfigService(config);
});
